你可以使用以下JavaScript代码来实现这个函数：

```javascript
function isPowerOfTwo(num) {
  return (num & (num - 1)) === 0 && num !== 0;
}

function sumDigits(num) {
  let sum = 0;
  while (num) {
    sum += num % 10;
    num = Math.floor(num / 10);
  }
  return sum;
}

function checkNumber(num) {
  if (isPowerOfTwo(num)) {
    const digitSum = sumDigits(num);
    return digitSum >= 10;
  }
  return false;
}

console.log(checkNumber(16)); // false
console.log(checkNumber(256)); // true
```

这个代码首先定义了一个`isPowerOfTwo`函数，用于检查一个数字是否是2的幂。然后定义了一个`sumDigits`函数，用于计算一个数字的各位数字之和。最后定义了`checkNumber`函数，它接收一个数字作为参数，检查该数字是否是2的幂，如果是，则计算其数字和，如果数字和不小于10，则返回`true`，否则返回`false`。如果该数字不是2的幂，则直接返回`false`。

