以下是使用Go语言开发的程式码，其中包含一个名为 `FindMax` 的函数。此函数接收一个由整数元素组成的阵列，并返回阵列中的最大数值。

```go
package main

import (
	"fmt"
)

// FindMax 函数接收一个整数阵列并返回其中的最大值
func FindMax(nums []int) int {
	max := nums[0] // 先将第一个元素设为最大值
	for _, num := range nums {
		if num > max {
			max = num // 如果当前元素比 max 大，则更新 max
		}
	}
	return max // 返回最大值
}

func main() {
	nums := []int{1, 3, 5, 7, 9, 2, 4, 6, 8}
	max := FindMax(nums)
	fmt.Println("最大值是：", max)
}
```

